const r = await tools.exec_command({cmd:"cat > recommendations.json <<'EOF'
{
  "stages": {
    "prototype": {
      "level": 4,
      "rationale": "For disposable exploration, speed and learning matter more than maintainability, so accepting code without reading it can be reasonable. Keep the prototype isolated and plan to discard or rebuild it before real users depend on it."
    },
    "proof-of-concept": {
      "level": 3,
      "rationale": "A stakeholder demo benefits from fast iteration, but it should behave reliably enough to support the claims being demonstrated. Review changes selectively and test the key flows; do not present a working demo as evidence of production readiness."
    },
    "mvp": {
      "level": 2,
      "rationale": "Early users create real security, privacy, and reliability obligations, and the code may become the foundation of the product. AI can write code, but a person should review every change line by line and validate it before release."
    },
    "production": {
      "level": 2,
      "rationale": "Paying customers and ongoing maintenance make regressions and hidden defects costly. Require line-by-line review of AI-written changes alongside the team's normal testing, security, and operational checks."
    },
    "critical": {
      "level": 1,
      "rationale": "For regulated or safety-critical systems, AI should be limited to suggestions that qualified people independently implement or rewrite. Apply the system's formal verification, traceability, validation, and approval requirements to all changes."
    }
  },
  "summary": "Use full vibe coding only for isolated, disposable prototypes. As real users, customer commitments, and safety obligations increase, require progressively stronger human ownership and review; critical systems should use AI as an advisor, not as the author of accepted code."
}
EOF
cat recommendations.json", max_output_tokens:3000});
text(r.output);

